"command": "python3 - <<'PY'
import json, os, importlib.util, sys, subprocess
mods=['pandas','numpy','matplotlib','seaborn','geopandas','shapely']
packages={}
for m in mods:
    spec=importlib.util.find_spec(m)
    packages[m]={'available': spec is not None}
    if spec:
        try:
            mod=__import__(m)
            packages[m]['version']=getattr(mod,'__version__','unknown')
        except Exception as e:
            packages[m]['version']='import_error:'+repr(e)
check={
 'python_version': sys.version.split()[0],
 'packages': packages,
 'capability_decisions':[
   {'need':'tabular analysis','implementation':'pandas/numpy','status':'available'},
